SELECT fs.figure_id, s.id, s.name, g.id AS group_id, g.name AS group_name FROM figure_series fs JOIN series s ON s.user_id = fs.user_id AND s.id = fs.series_id JOIN series_group g ON g.user_id = s.user_id AND g.id = s.group_id WHERE fs.user_id = #{userId} AND fs.figure_id IN
#{figureId}
ORDER BY fs.figure_id, s.id
